-- 1178: подробный состав туров «Края Вулканов» (#2245).
--
-- Владелец 08.10: «нужно подробное описание, что входит в тур». В 1176 блок
-- «Что включено» повторял сайт оператора дословно («питание согласно
-- программе», «проживание в гостиницах») — туристу не видно, сколько ночей
-- в палатке и есть ли ужин. Здесь те же факты разложены по строкам, и всё —
-- со страниц volcanoesland.ru (проба 712):
--  - ночёвки: по статистике страницы и программе (гостиница / домики /
--    палатки, где именно);
--  - питание: счёт по кодам дней программы (З/О/У), не на глаз;
--  - перелёты, переезды, команда, снаряжение, программа на месте — с той же
--    страницы;
--  - «не входит»: то, что сайт называет сам, плюс две строки, выведенные из
--    его же текста: перелёт до Камчатки (каждый многодневный тур начинается
--    со встречи в аэропорту Елизово) и личное снаряжение (сайт отсылает к
--    своему списку и не включает его в цену). Ужины у тура 01 — по кодам
--    программы: ни одного «У».
--
-- Пишется только туда, где состав ещё ровно тот, что положила 1176:
-- поправленное оператором в кабинете не затирается.

UPDATE operator_tours t
   SET included = v.inc,
       not_included = v.ninc,
