   ARRAY['проживание: 2 ночи в гостинице (Паратунка или Петропавловск-Камчатский), 5 ночей в палаточных лагерях (Паужетка, кордон Озёрный на Курильском озере)', 'питание по программе: 6 завтраков, 6 обедов и 6 ужинов', 'переезды на автомобиле до Паужетки и обратно с паромными переправами через реки Большая, Опала и Кошегочек', 'все сборы Кроноцкого заповедника за услуги на Курильском озере', 'наблюдение за медведями и экскурсия на лодках по Курильскому озеру', 'команда: гид и повар', 'общее снаряжение: палатки, кемпинговое оборудование, посуда']::text[],
   ARRAY['личное снаряжение — список у оператора (раздел «Важная информация» на его сайте)', 'авиаперелёт до Петропавловска-Камчатского и обратно (тур начинается со встречи в аэропорту Елизово)']::text[],
   ARRAY['проживание в гостиницах и гостевых домах', 'автомобильные переезды по всему маршруту', 'питание согласно программе тура', 'сопровождение группы: гид и повар', 'все сборы Кроноцкого заповедника за услуги на Курильском озере', 'общее туристическое снаряжение: палатки, кемпинговое оборудование, посуда']::text[],
   ARRAY[]::text[])
  ) AS v(slug, inc, ninc, old_inc, old_ninc)
  JOIN partners p ON p.slug = 'volcanoesland'
 WHERE t.operator_id::text = p.id::text
   AND t.slug = v.slug
   AND t.included IS NOT DISTINCT FROM v.old_inc
   AND t.not_included IS NOT DISTINCT FROM v.old_ninc;
